package studio.jiayu.neoagent;
public class TaskScopeTest {static int n;static void yes(boolean b){if(!b)throw new AssertionError("Scope check "+n);n++;}public static void main(String[] args){String text="先在淘宝只查价，不加购；然后在美团查看电影到订单核对页，不提交付款。";String taobao=TaskScope.forPackage("com.taobao.taobao",text),meituan=TaskScope.forPackage("com.sankuai.meituan",text);yes(taobao.contains("只查价")&&!taobao.contains("订单核对"));yes(!ShoppingIntent.preview(taobao));yes(ShoppingIntent.preview(meituan));yes(!meituan.contains("不加购"));String doc="在WPS新建合同，租金每月10日；然后打开美团看电影；最后再在WPS只改每月5日并保存。";String scope=TaskScope.forPackage("cn.wps.moffice_eng",doc);yes(scope.contains("每月10日")&&scope.contains("每月5日")&&!scope.contains("看电影"));yes(TaskScope.forPackage("com.jingdong.app.mall",text).isEmpty());yes(TaskScope.forPackage("cn.wps.moffice_eng","在WPS新建合同").equals("在WPS新建合同"));yes(TaskScope.forPackage("com.sankuai.meituan","先在淘宝比价，然后去美团外卖核对订单核对页").contains("核对订单"));System.out.println("PASS: "+n+" original per-app scope checks");}}
